using System.Text.Json.Nodes;
using TouhouLastWorld;

internal sealed partial class RegressionSuite
{
    private void Scenario03()
    {
        Check(equipmentReload.Dispatch("unit_equip_picture", arguments: new(1, Equipment: [new(0, 11)])).Status == 400, "equipment slot bounds enforced");
        Check(equipmentReload.Dispatch("unit_equip_picture", arguments: new(1, Equipment: [new(1, 11), new(1, 0)])).Status == 400, "duplicate equipment slot rejected");
        var equippedUpdate = equipmentReload.Dispatch("unit_equip_picture", arguments: new(1, Equipment: [new(1, 11)])).Body!["user_update"]!;
        Check(equippedUpdate["unit"]!["unit_list"]![0]!["equip_spellcard1_user_picture_id"]!.GetValue<long>() == 11 && equippedUpdate["picture"]!["picture_list"]![0]!["equip_user_unit_id"]!.GetValue<long>() == 1, "equipment assignment updates both references");
        Check(equipmentReload.Dispatch("unit_equip_picture", arguments: new(1, Equipment: [new(2, 11)])).Status == 409, "same equipment cannot fill two slots");
        Check(equipmentReload.Dispatch("unit_equip_picture", arguments: new(1, Equipment: [new(1, 0), new(2, 999)])).Status == 404 && equipmentReload.Dispatch("login").Body!["user"]!["unit"]!["unit_list"]![0]!["equip_spellcard1_user_picture_id"]!.GetValue<long>() == 11, "invalid batch leaves earlier assignments unchanged");
        Check(equipmentReload.Dispatch("unit_equip_picture", arguments: new(1, Equipment: [new(2, 12)])).Status == 409, "equipment owned by another unit must be released");
        Check(equipmentReload.Dispatch("unit_equip_picture", arguments: new(1, Equipment: [new(1, 0), new(2, 11)])).Status == 0, "equipment can move between slots in one batch");
        var equippedReload = new OfflineServer(new JsonStateStore(equipmentDirectory), equipmentSeed.ToJsonString(), "offline://resources/");
        equippedReload.Dispatch("game_init");
        var equippedUser = equippedReload.Dispatch("login").Body!["user"]!;
        Check(equippedUser["unit"]!["unit_list"]![0]!["equip_spellcard1_user_picture_id"]!.GetValue<long>() == 0 && equippedUser["unit"]!["unit_list"]![0]!["equip_spellcard2_user_picture_id"]!.GetValue<long>() == 11, "equipment slot move persists");
        Console.WriteLine("Passed 8 equipment assignment checks.");
        var costumeSeed = JsonNode.Parse(seed)!.AsObject();
        costumeSeed["costume"]!["costume_id_list"]!.AsArray().Add(100102);
        var costumeDirectory = directory + "-costume";
        var costumes = new OfflineServer(new JsonStateStore(costumeDirectory), costumeSeed.ToJsonString(), "offline://resources/");
        costumes.Dispatch("game_init");
        costumes.Dispatch("login");
        Check(costumes.Dispatch("unit_equip_costume", arguments: new(Costumes: [new(1, 100102, 999, false)])).Status == 400, "costume definition must match unit");
        Check(costumes.Dispatch("unit_equip_costume", arguments: new(Costumes: [new(1, 100103, 1001, false)])).Status == 403, "unowned costume rejected");
        Check(costumes.Dispatch("unit_equip_costume", arguments: new(Costumes: [new(1, 100102, 1001, false), new(999, 100102, 1001, false)])).Status == 404 && costumes.Dispatch("login").Body!["user"]!["unit"]!["unit_list"]![0]!["equip_costume_id"]!.GetValue<int>() == 100101, "costume batch failure preserves earlier assignments");
        Check(costumes.Dispatch("unit_equip_costume", arguments: new(Costumes: [new(1, 100102, 1001, false)])).Status == 0, "owned costume accepted");
        var costumeReload = new OfflineServer(new JsonStateStore(costumeDirectory), costumeSeed.ToJsonString(), "offline://resources/");
        costumeReload.Dispatch("game_init");
        var costumeUser = costumeReload.Dispatch("login").Body!["user"]!;
        Check(costumeUser["unit"]!["unit_list"]![0]!["equip_costume_id"]!.GetValue<int>() == 100102 && costumeUser["costume"]!["costume_id_list"]!.AsArray().Count == 1, "costume persists without unlocking new entries");
        Check(costumeReload.Dispatch("unit_equip_costume", arguments: new(Costumes: [new(1, 100101, 1001, true)])).Status == 0, "default costume can be restored");
        Console.WriteLine("Passed 6 costume checks.");
        var dispatchSeed = JsonNode.Parse(seed)!.AsObject();
        dispatchSeed["dispatch"]!["dispatch_list"] = new JsonArray(new JsonObject { ["user_dispatch_id"] = 10L, ["dispatch_id"] = 1, ["user_unit_id_list"] = new JsonArray(1L) }, new JsonObject { ["user_dispatch_id"] = 11L, ["dispatch_id"] = 2, ["user_unit_id_list"] = new JsonArray(2L) });
        var dispatchDirectory = directory + "-dispatch";
        var dispatches = new OfflineServer(new JsonStateStore(dispatchDirectory), dispatchSeed.ToJsonString(), "offline://resources/");
        dispatches.Dispatch("game_init");
        var beforeDispatchCancel = dispatches.Dispatch("login").Body!["user"]!;
        Check(dispatches.Dispatch("dispatch_cancel", arguments: new(EntityId: 0)).Status == 400, "invalid dispatch ID rejected");
        Check(dispatches.Dispatch("dispatch_cancel", arguments: new(EntityId: 99)).Status == 404, "unknown dispatch rejected");
        var cancelledDispatch = dispatches.Dispatch("dispatch_cancel", arguments: new(EntityId: 10)).Body!;
        Check(cancelledDispatch["remove_user_dispatch_id"]!.GetValue<long>() == 10 && cancelledDispatch["user_update"]!["dispatch"]!["dispatch_list"]!.AsArray().Count == 1, "dispatch cancellation includes native deletion marker");
        var dispatchReload = new OfflineServer(new JsonStateStore(dispatchDirectory), dispatchSeed.ToJsonString(), "offline://resources/");
        dispatchReload.Dispatch("game_init");
        var dispatchUser = dispatchReload.Dispatch("login").Body!["user"]!;
        Check(dispatchUser["dispatch"]!["dispatch_list"]![0]!["user_dispatch_id"]!.GetValue<long>() == 11, "dispatch cancellation persists and preserves unrelated task");
        Check(JsonNode.DeepEquals(beforeDispatchCancel["unit"], dispatchUser["unit"]) && JsonNode.DeepEquals(dispatchSeed["orb"], dispatchUser["orb"]), "dispatch cancellation does not fabricate rewards");
        Console.WriteLine("Passed 5 dispatch cancellation checks.");
        var weeklyInfo = dispatchReload.Dispatch("multiple_spirits_weekly_top", arguments: new(Ids: [])).Body!;
        Check(weeklyInfo["clear_info"]!.AsArray().Count == 0, "weekly progress starts empty");
        weeklyInfo["clear_info"]!.AsArray().Add(new JsonObject());
        Check(dispatchReload.Dispatch("multiple_spirits_weekly_top", arguments: new(Ids: [])).Body!["clear_info"]!.AsArray().Count == 0, "weekly response template remains isolated");
        Console.WriteLine("Passed 2 weekly query checks.");
        var passOverview = dispatchReload.Dispatch("battle_pass_top").Body!;
        Check(new[] { "unlock_list", "clear_list", "received_list" }.All(field => passOverview["battle_pass_mission"]![field]!.AsArray().Count == 0), "pass mission groups are nonnull empty lists");
        Check(new[] { "normal_received_reward_level", "premium_received_reward_level_1", "premium_received_reward_level_2" }.All(field => passOverview[field]!.GetValue<int>() == 0), "no pass reward levels fabricated");
        Check(dispatchReload.Dispatch("rhythm_game_top").Body!["clear_info"]!.AsArray().Count == 0, "score overview starts empty");
        Console.WriteLine("Passed 3 overview query checks.");
        var rhythmDirectory = directory + "-rhythm";
        var rhythm = new OfflineServer(new JsonStateStore(rhythmDirectory), seed, "offline://resources/");
        rhythm.Dispatch("game_init");
        rhythm.Dispatch("login");
        Check(rhythm.Dispatch("rhythm_game_start", arguments: new(1, 0)).Status == 404, "missing music definition rejected");
        Check(rhythm.Dispatch("rhythm_game_end", arguments: new(Rhythm: new(1, 2, 100, 90, 2))).Status == 409, "result without start rejected");
        Check(rhythm.Dispatch("rhythm_game_start", arguments: new(1, 1)).Status == 0, "known music starts");
        Check(rhythm.Dispatch("rhythm_game_end", arguments: new(Rhythm: new(1, 0, 100, 90, 2))).Status == 400 && rhythm.Dispatch("rhythm_game_end", arguments: new(Rhythm: new(1, 2, 100, float.NaN, 2))).Status == 400, "invalid wire difficulty and nonfinite rate rejected");
        var rhythmEnded = rhythm.Dispatch("rhythm_game_end", arguments: new(Rhythm: new(1, 2, 100, 90, 2)));
        Check(rhythmEnded.Status == 0 && rhythmEnded.Body!["reward_list"]!.AsArray().Count == 0 && rhythmEnded.Body["remaining_phantasm_point"]!.GetValue<int>() == 0, "result persists without reward allocation");
        Check(rhythm.Dispatch("rhythm_game_end", arguments: new(Rhythm: new(1, 2, 200, 95, 3))).Status == 409, "duplicate completion rejected");
        rhythm.Dispatch("rhythm_game_start", arguments: new(1, 1));
        rhythm.Dispatch("rhythm_game_end", arguments: new(Rhythm: new(1, 2, 50, 95, 1)));
        rhythm.Dispatch("rhythm_game_start", arguments: new(1, 1));
        rhythm.Dispatch("rhythm_game_end", arguments: new(Rhythm: new(1, 3, 20, 50, 1)));
        var rhythmReload = new OfflineServer(new JsonStateStore(rhythmDirectory), seed, "offline://resources/");
        rhythmReload.Dispatch("game_init");
        var rhythmUser = rhythmReload.Dispatch("login").Body!["user"]!;
        var savedScores = rhythmReload.Dispatch("rhythm_game_top").Body!["clear_info"]!.AsArray();
        Check(savedScores.Count == 2 && savedScores[0]!["highest_score"]!.GetValue<int>() == 100 && savedScores[0]!["highest_rate"]!.GetValue<float>() == 95 && savedScores[0]!["rank"]!.GetValue<int>() == 2, "independent best values persist by difficulty");
        Check(JsonNode.DeepEquals(rhythmUser["phantasm_point"], JsonNode.Parse(seed)!["phantasm_point"]), "rhythm completion preserves held points");
        Console.WriteLine("Passed 8 rhythm checks.");
        var achievementSeed = JsonNode.Parse(seed)!.AsObject();
        achievementSeed["_local_achievements"] = new JsonArray(new JsonObject { ["achievement_id"] = 10, ["current_value"] = 1, ["is_new"] = 0, ["is_acquired"] = 1 }, new JsonObject { ["achievement_id"] = 20, ["current_value"] = 0, ["is_new"] = 0, ["is_acquired"] = 0 });
        var achievementDirectory = directory + "-achievement";
        var achievements = new OfflineServer(new JsonStateStore(achievementDirectory), achievementSeed.ToJsonString(), "offline://resources/");
        achievements.Dispatch("game_init");
        achievements.Dispatch("login");
        Check(achievements.Dispatch("achievement_select", arguments: new(Value: 20)).Status == 403 && achievements.Dispatch("achievement_select", arguments: new(Value: 99)).Status == 403, "unacquired selections rejected");
        Check(achievements.Dispatch("achievement_select", arguments: new(Value: 10)).Body!["user_update"]!["achievement"]!["selected_achievement_id"]!.GetValue<int>() == 10, "selection returns native user update");
        var achievementReload = new OfflineServer(new JsonStateStore(achievementDirectory), achievementSeed.ToJsonString(), "offline://resources/");
        achievementReload.Dispatch("game_init");
        Check(achievementReload.Dispatch("login").Body!["user"]!["achievement"]!["selected_achievement_id"]!.GetValue<int>() == 10, "selection survives reload");
        Check(achievementReload.Dispatch("achievement_select", arguments: new(Value: 0)).Status == 0 && achievementReload.Dispatch("achievement_top").Body!["achievement_list"]!.AsArray().Count == 2, "clearing selection preserves collection");
        Check(achievementReload.Dispatch("update_voice_version").Status == 0, "voice notification receives minimal response");
        Console.WriteLine("Passed 5 selection and notification checks.");
        var deckDirectory = directory + "-decks";
        var decks = new OfflineServer(new JsonStateStore(deckDirectory), seed, "offline://resources/");
        decks.Dispatch("game_init");
        decks.Dispatch("login");
        Check(decks.Dispatch("roguelite_deck_save", arguments: new(Value: -1, Ids: [1], Text: "A")).Status == 400 && decks.Dispatch("roguelite_deck_save", arguments: new(Value: 1, Ids: [0], Text: "A")).Status == 400, "invalid preset number and entry rejected");
        Check(decks.Dispatch("roguelite_deck_save", arguments: new(Value: 1, Ids: [3, 2, 3], Text: "A")).Status == 0, "preset preserves ordered entries and repeated copies");
        decks.Dispatch("roguelite_deck_save", arguments: new(Value: 2, Ids: [], Text: "B"));
        Check(decks.Dispatch("roguelite_deck_call", arguments: new(Value: 99)).Status == 404, "missing preset rejected");
        Check(decks.Dispatch("roguelite_deck_call", arguments: new(Value: 1)).Status == 0, "saved preset activates");
        var deckReload = new OfflineServer(new JsonStateStore(deckDirectory), seed, "offline://resources/");
        deckReload.Dispatch("game_init");
        var savedDecks = deckReload.Dispatch("login").Body!["user"]!["_local_saved_decks"]!;
        Check(savedDecks["0"]!["deck_no"]!.GetValue<int>() == 0 && savedDecks["0"]!["deck_name"]!.GetValue<string>() == "A" && JsonNode.DeepEquals(savedDecks["0"]!["deck_list"], new JsonArray(3, 2, 3)), "active preset survives reload");
        Check(savedDecks["1"]!["deck_no"]!.GetValue<int>() == 1 && savedDecks["2"]!["deck_list"]!.AsArray().Count == 0, "activation preserves source and other presets");
        Console.WriteLine("Passed 6 deck checks.");
        Check(deckReload.Dispatch("roguelite_top").Status == 503, "overview requires master capacity");
        var deckOverview = deckReload.Dispatch("roguelite_top", arguments: new(Value: 3)).Body!;
        Check(deckOverview["saved_decks"]!.AsArray().Select(entry => entry!["deck_no"]!.GetValue<int>()).SequenceEqual(new[] { 0, 1, 2, 3 }) && JsonNode.DeepEquals(deckOverview["saved_decks"]![1]!["deck_list"], new JsonArray(3, 2, 3)), "overview fills numbered slots and retains saved preset");
        Check(deckOverview["progress"]!.GetValue<int>() == 0 && deckOverview["map_id"]!.GetValue<int>() == 0 && deckOverview["play_details"]!.GetValue<string>() == "", "overview does not fabricate active progress");
        Check(deckReload.Dispatch("roguelite_deck_call", arguments: new(Value: 3)).Status == 0, "initialized empty preset can be activated");
        Console.WriteLine("Passed 4 deck overview checks.");
        var pageSeed = JsonNode.Parse(seed)!.AsObject();
        pageSeed["comic_point"] = 100;
        var pageDirectory = directory + "-pages";
        var pages = new OfflineServer(new JsonStateStore(pageDirectory), pageSeed.ToJsonString(), "offline://resources/");
        pages.Dispatch("game_init");
        pages.Dispatch("login");
        Check(pages.Dispatch("comic_get_pages").Status == 503, "page acquisition needs master definition");
        Check(pages.Dispatch("comic_get_pages", arguments: new(Pages: new(1, 11, 10, 5))).Status == 409 && pages.Dispatch("comic_get_pages", arguments: new(Pages: new(1, 10, 10, 20))).Status == 409, "page limit and insufficient balance rejected");
        Check(pages.Dispatch("comic_read_end", arguments: new(1, 1)).Status == 404, "unacquired collection cannot be marked read");
        var acquiredPages = pages.Dispatch("comic_get_pages", arguments: new(Pages: new(1, 3, 10, 5))).Body!["user_update"]!;
        Check(acquiredPages["comic_point"]!.GetValue<int>() == 85 && acquiredPages["comic_data"]![0]!["received_page_count"]!.GetValue<int>() == 3, "page acquisition deducts matching point cost");
        Check(pages.Dispatch("comic_read_end", arguments: new(1, 4)).Status == 403, "unacquired page cannot be marked read");
        pages.Dispatch("comic_read_end", arguments: new(1, 3));
        pages.Dispatch("comic_read_end", arguments: new(1, 1));
        pages.Dispatch("comic_get_pages", arguments: new(Pages: new(1, 2, 10, 5)));
        var pageReload = new OfflineServer(new JsonStateStore(pageDirectory), pageSeed.ToJsonString(), "offline://resources/");
        pageReload.Dispatch("game_init");
        var pageUser = pageReload.Dispatch("login").Body!["user"]!;
        Check(pageUser["comic_point"]!.GetValue<int>() == 75 && pageUser["comic_data"]![0]!["received_page_count"]!.GetValue<int>() == 5 && pageUser["comic_data"]![0]!["rad_page_count"]!.GetValue<int>() == 3, "page balance and monotonic reading progress survive reload");
        Check(pageReload.Dispatch("comic_get_pages", arguments: new(Pages: new(1, int.MaxValue, int.MaxValue, int.MaxValue))).Status == 409 && pageReload.Dispatch("login").Body!["user"]!["comic_point"]!.GetValue<int>() == 75, "overflow-sized request preserves balance");
        Console.WriteLine("Passed 7 page checks.");
        var seriesSeed = JsonNode.Parse(seed)!.AsObject();
        seriesSeed["series_battle_status"]!["episode_id"] = 10;
        seriesSeed["series_battle_status"]!["progress"] = 3;
        seriesSeed["series_battle_status"]!["use_replays"] = new JsonArray(1, 2);
        seriesSeed["_local_series_replays"] = new JsonObject
        {
            ["1:1"] = "saved"
        };
        var seriesDirectory = directory + "-series-reset";
        var series = new OfflineServer(new JsonStateStore(seriesDirectory), seriesSeed.ToJsonString(), "offline://resources/");
        series.Dispatch("game_init");
        var beforeSeriesReset = series.Dispatch("login").Body!["user"]!;
        var resetSeries = series.Dispatch("series_battle_reset").Body!["user_update"]!["series_battle_status"]!;
        Check(resetSeries["episode_id"]!.GetValue<int>() == 0 && resetSeries["progress"]!.GetValue<int>() == 0 && resetSeries["use_replays"]!.AsArray().Count == 0, "series reset clears active state");
        Check(series.Dispatch("series_battle_reset").Status == 0, "series reset is repeatable");
        var seriesReload = new OfflineServer(new JsonStateStore(seriesDirectory), seriesSeed.ToJsonString(), "offline://resources/");
        seriesReload.Dispatch("game_init");
        var seriesUser = seriesReload.Dispatch("login").Body!["user"]!;
        Check(seriesUser["series_battle_status"]!["progress"]!.GetValue<int>() == 0 && JsonNode.DeepEquals(seriesUser["_local_series_replays"], seriesSeed["_local_series_replays"]) && JsonNode.DeepEquals(seriesUser["unit"], beforeSeriesReset["unit"]) && JsonNode.DeepEquals(seriesUser["gold"], seriesSeed["gold"]), "series reset persists without changing collection or rewards");
        Console.WriteLine("Passed 3 series reset checks.");
        var seriesOverview = seriesReload.Dispatch("series_battle_ranking_top").Body!;
        Check(seriesOverview["is_held"]!.GetValue<int>() == 0 && seriesOverview["ranking"]!.GetValue<int>() == 0 && seriesOverview["score_info"]!.AsArray().Count == 0, "ranking overview remains inactive without scores");
        Console.WriteLine("Passed 1 ranking overview check.");
        var seriesTeamDirectory = directory + "-series-teams";
        var seriesTeams = new OfflineServer(new JsonStateStore(seriesTeamDirectory), seed, "offline://resources/");
        seriesTeams.Dispatch("game_init");
        seriesTeams.Dispatch("login");
        Check(seriesTeams.Dispatch("series_battle_team_update", arguments: new(SeriesTeams: [new(1, [1])])).Status == 400 && seriesTeams.Dispatch("series_battle_team_update", arguments: new(SeriesTeams: [new(80, [1, 1])])).Status == 400, "series update rejects ordinary slots and duplicate members");
        Check(seriesTeams.Dispatch("series_battle_team_update", arguments: new(SeriesTeams: [new(80, [1]), new(81, [999])])).Status == 404 && seriesTeams.Dispatch("login").Body!["user"]!["team"]!["team_list"]!.AsArray().Count == 1, "invalid member rolls back entire series batch");
        Check(seriesTeams.Dispatch("series_battle_team_update", arguments: new(SeriesTeams: [new(80, [1]), new(81, [])])).Status == 0, "series slots created together");
        var seriesTeamReload = new OfflineServer(new JsonStateStore(seriesTeamDirectory), seed, "offline://resources/");
        seriesTeamReload.Dispatch("game_init");
        var savedSeriesTeams = seriesTeamReload.Dispatch("login").Body!["user"]!["team"]!["team_list"]!.AsArray();
        Check(savedSeriesTeams.Count == 3 && savedSeriesTeams[1]!["user_unit_id_list"]!.AsArray().Count == 6 && savedSeriesTeams[1]!["user_unit_id_list"]![0]!.GetValue<long>() == 1 && JsonNode.DeepEquals(savedSeriesTeams[0], JsonNode.Parse(seed)!["team"]!["team_list"]![0]), "series teams persist and preserve ordinary team");
        var activeSeriesTeams = new OfflineServer(new JsonStateStore(directory + "-active-series-teams"), seriesSeed.ToJsonString(), "offline://resources/");
        activeSeriesTeams.Dispatch("game_init");
        activeSeriesTeams.Dispatch("login");
        Check(activeSeriesTeams.Dispatch("series_battle_team_update", arguments: new(SeriesTeams: [new(80, [1])])).Status == 409, "active series roster cannot be replaced");
        Console.WriteLine("Passed 5 series team checks.");
    }
}
